import pandas as pd
import numpy as np

# Define indicators
def williams_r(high, low, close, period=14):
    highest_high = high.rolling(window=period).max()
    lowest_low = low.rolling(window=period).min()
    return -100 * ((highest_high - close) / (highest_high - lowest_low))

def obv(close, volume):
    obv = np.zeros(len(close))
    obv[0] = volume[0]
    for i in range(1, len(close)):
        if close[i] > close[i-1]:
            obv[i] = obv[i-1] + volume[i]
        elif close[i] < close[i-1]:
            obv[i] = obv[i-1] - volume[i]
        else:
            obv[i] = obv[i-1]
    return obv

def volume_profile(volume, length=20):
    vp = np.zeros(len(volume))
    for i in range(length, len(volume)):
        vp[i] = np.mean(volume[i-length:i])
    return vp

def cci(high, low, close, period=20):
    tp = (high + low + close) / 3
    cci = (tp - tp.rolling(window=period).mean()) / (0.015 * tp.rolling(window=period).std())
    return cci

# Define entry and exit rules
def entry_rules(data):
    long_entry = (williams_r(data['High'], data['Low'], data['Close']) > -50) & (obv(data['Close'], data['Volume']) > obv(data['Close'], data['Volume']).shift(1)) & (volume_profile(data['Volume']) > volume_profile(data['Volume']).shift(1)) & (cci(data['High'], data['Low'], data['Close']) > 0) & (data['Close'] > data['Close'].shift(1) * 1.01)
    short_entry = (williams_r(data['High'], data['Low'], data['Close']) < -50) & (obv(data['Close'], data['Volume']) < obv(data['Close'], data['Volume']).shift(1)) & (volume_profile(data['Volume']) < volume_profile(data['Volume']).shift(1)) & (cci(data['High'], data['Low'], data['Close']) < 0) & (data['Close'] < data['Close'].shift(1) * 0.99)
    return long_entry, short_entry

def exit_rules(data):
    long_exit = (williams_r(data['High'], data['Low'], data['Close']) < -50) | (obv(data['Close'], data['Volume']) < obv(data['Close'], data['Volume']).shift(1)) | (volume_profile(data['Volume']) < volume_profile(data['Volume']).shift(1)) | (cci(data['High'], data['Low'], data['Close']) < 0) | (data['Close'] < data['Close'].shift(1) * 0.99)
    short_exit = (williams_r(data['High'], data['Low'], data['Close']) > -50) | (obv(data['Close'], data['Volume']) > obv(data['Close'], data['Volume']).shift(1)) | (volume_profile(data['Volume']) > volume_profile(data['Volume']).shift(1)) | (cci(data['High'], data['Low'], data['Close']) > 0) | (data['Close'] > data['Close'].shift(1) * 1.01)
