def stop_loss(data, percentage=0.05):
    return data['Close'] * (1 - percentage)

def take_profit(data, percentage=0.1):
    return data['Close'] * (1 + percentage)

# Define trading logic
def trading_logic(data):
    long_entry, short_entry = entry_rules(data)
    long_exit, short_exit = exit_rules(data)

    positions = np.zeros(len(data))
    for i in range(1, len(data)):
        if long_entry[i]:
            positions[i] = position_sizing(data.iloc[i])
        elif short_entry[i]:
            positions[i] = -position_sizing(data.iloc[i])
        elif long_exit[i] and positions[i-1] > 0:
